"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[4141],{4141(e,s,n){n.d(s,{content:()=>o,description:()=>i,keywords:()=>r,title:()=>a});n(5043);var t=n(579);const a="OCDE : \xe9valuer le processus, pas le produit, en sciences",i="Le Digital Education Outlook 2026 de l'OCDE recommande officiellement 'l'\xe9valuation orient\xe9e processus' pour l'\xe8re de l'IA. Cette validation internationale confirme ce que WhimsyLabs construit depuis le d\xe9but.",r=["\xe9valuation processus OCDE","notation orient\xe9e processus","\xe9valuation \xe9ducation IA","\xe9valuation laboratoire virtuel","notation bas\xe9e sur la technique","OECD Digital Education Outlook 2026","\xe9valuation formative IA","\xe9ducation STEM","tuteur IA"],o=(0,t.jsxs)(t.Fragment,{children:[(0,t.jsxs)("p",{children:["Lorsque l'OCDE a publi\xe9 son Digital Education Outlook 2026 en janvier, une recommandation s'est d\xe9marqu\xe9e des autres : les \xe9coles devraient s'orienter vers \"l'\xe9valuation orient\xe9e processus\". Le rapport de 245 pages, qui a examin\xe9 la recherche internationale sur l'IA g\xe9n\xe9rative dans l'\xe9ducation, a conclu que \"les mod\xe8les d'\xe9valuation traditionnels qui se concentrent uniquement sur les r\xe9sultats finaux deviennent inad\xe9quats.\" Au lieu de cela, l'OCDE a exhort\xe9 les \xe9ducateurs \xe0 \xe9valuer \"non seulement ce que les \xe9tudiants produisent, mais comment ils s'engagent dans l'apprentissage pour cr\xe9er des produits\" (",(0,t.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"OCDE, 2026"}),")."]}),(0,t.jsx)("p",{children:"Ce n'est pas une orientation politique incr\xe9mentale. Cela repr\xe9sente un changement fondamental dans la fa\xe7on dont les organismes internationaux pensent l'\xe9valuation des \xe9tudiants \xe0 une \xe9poque o\xf9 l'IA peut g\xe9n\xe9rer des essais, r\xe9soudre des \xe9quations et m\xeame concevoir des exp\xe9riences en quelques secondes. Pour nous chez WhimsyLabs, cela repr\xe9sente \xe9galement autre chose : une validation internationale d'une approche que nous construisons depuis notre fondation."}),(0,t.jsx)("h2",{children:"Que recommande exactement l'OCDE ?"}),(0,t.jsxs)("p",{children:["Le rapport de l'OCDE est sans \xe9quivoque : lorsque l'IA peut produire instantan\xe9ment des r\xe9sultats soign\xe9s, noter ces r\xe9sultats ne dit presque rien sur l'apprentissage de l'\xe9tudiant. La solution, selon le rapport, est d'\xe9valuer le processus \xe0 la place. Comme le r\xe9sume la Plateforme europ\xe9enne pour l'\xe9ducation des adultes, l'OCDE sugg\xe8re qu'\"au lieu de noter le travail final, les enseignants devraient \xe9valuer comment un \xe9tudiant a interagi avec l'IA, comment il a critiqu\xe9 sa production et comment il a affin\xe9 ses id\xe9es au fil du temps\" (",(0,t.jsx)("a",{href:"https://epale.ec.europa.eu/en/blog/future-learning-key-takeaways-oecd-digital-education-outlook-2026",target:"_blank",rel:"noopener noreferrer",children:"EPALE, 2026"}),")."]}),(0,t.jsx)("p",{children:"Cette recommandation d\xe9coule de recherches montrant un paradoxe troublant : les \xe9tudiants utilisant l'IA r\xe9ussissent mieux aux t\xe2ches imm\xe9diates mais moins bien lorsque l'IA est retir\xe9e. Le rapport cite des \xe9tudes montrant que si les \xe9tudiants assist\xe9s par l'IA r\xe9ussissaient 48% mieux \xe0 accomplir des t\xe2ches, leurs performances chutaient de 17% lorsqu'ils \xe9taient test\xe9s sans support IA. L'OCDE appelle ce ph\xe9nom\xe8ne \"d\xe9lestage cognitif\", o\xf9 les \xe9tudiants laissent l'IA penser \xe0 leur place et manquent la lutte mentale n\xe9cessaire \xe0 un apprentissage authentique."}),(0,t.jsxs)("p",{children:["La pr\xe9occupation n'est pas hypoth\xe9tique. RTE a rapport\xe9 l'avertissement de l'OCDE selon lequel \"si elle est utilis\xe9e comme raccourci plut\xf4t que comme outil d'apprentissage, l'IA peut d\xe9placer l'effort cognitif et affaiblir les comp\xe9tences qui sous-tendent l'apprentissage profond.\" Le rapport met explicitement en garde contre \"le mirage de la fausse ma\xeetrise, o\xf9 les productions impressionnantes g\xe9n\xe9r\xe9es par l'IA masquent le sous-d\xe9veloppement des comp\xe9tences essentielles\" (",(0,t.jsx)("a",{href:"https://www.rte.ie/news/education/2026/0119/1553973-ai-education/",target:"_blank",rel:"noopener noreferrer",children:"RTE, 2026"}),")."]}),(0,t.jsx)("h2",{children:"Pourquoi l'\xe9valuation traditionnelle ne peut pas s'adapter"}),(0,t.jsx)("p",{children:"Le probl\xe8me fondamental avec l'\xe9valuation traditionnelle est qu'elle a \xe9t\xe9 con\xe7ue pour mesurer des r\xe9sultats \xe0 une \xe9poque o\xf9 les r\xe9sultats n\xe9cessitaient un effort humain. Lorsqu'un \xe9tudiant soumettait un essai en 1990, la qualit\xe9 de cet essai \xe9tait raisonnablement bien corr\xe9l\xe9e avec la compr\xe9hension de l'\xe9tudiant. L'\xe9tudiant devait r\xe9fl\xe9chir \xe0 l'argumentation, structurer ses id\xe9es et produire une prose refl\xe9tant sa compr\xe9hension. Le r\xe9sultat \xe9tait, en un sens significatif, une preuve du processus."}),(0,t.jsx)("p",{children:"Cette corr\xe9lation est rompue. Un \xe9tudiant peut maintenant demander \xe0 une IA de g\xe9n\xe9rer un essai sophistiqu\xe9 en quelques secondes, le soumettre avec des modifications mineures et recevoir de bonnes notes sans avoir rien appris. Les enseignants rapportent passer de plus en plus de temps \xe0 essayer de d\xe9tecter le travail g\xe9n\xe9r\xe9 par l'IA, du temps qui pourrait \xeatre consacr\xe9 \xe0 l'enseignement r\xe9el."}),(0,t.jsx)("p",{children:"Le rapport de l'OCDE indique clairement que la d\xe9tection n'est pas la solution. Le contenu g\xe9n\xe9r\xe9 par l'IA ne fera que devenir plus difficile \xe0 identifier, et la course aux armements de d\xe9tection d\xe9tourne l'\xe9nergie \xe9ducative de l'apprentissage vers la surveillance. La solution n'est pas d'attraper les tricheurs mais de changer ce que nous \xe9valuons. Si nous \xe9valuons le processus, pas le produit, l'IA devient un outil plut\xf4t qu'une menace."}),(0,t.jsx)("h2",{children:"Pourquoi les laboratoires scientifiques sont l'\xe9tude de cas parfaite"}),(0,t.jsx)("p",{children:"Nulle part la distinction entre processus et produit n'est plus \xe9vidente qu'en science de laboratoire. Lorsqu'un \xe9tudiant effectue un titrage et rapporte la molarit\xe9 correcte, qu'a-t-il r\xe9ellement d\xe9montr\xe9 ? Il a peut-\xeatre raisonn\xe9 syst\xe9matiquement \xe0 travers la proc\xe9dure, fait des observations soigneuses et compris la chimie sous-jacente. Ou il a peut-\xeatre demand\xe9 la r\xe9ponse \xe0 un voisin, copi\xe9 le rapport de l'ann\xe9e derni\xe8re ou simplement eu de la chance. Le nombre final ne dit presque rien."}),(0,t.jsx)("p",{children:"Ce probl\xe8me existait avant l'IA, mais l'IA l'a rendu urgent. Un \xe9tudiant peut maintenant demander \xe0 ChatGPT d'\xe9crire un rapport de laboratoire complet, incluant des observations plausibles, une analyse d'erreur appropri\xe9e et des conclusions bien raisonn\xe9es, sans jamais toucher l'\xe9quipement. Le rapport semble correct parce que l'IA peut synth\xe9tiser \xe0 quoi ressemblent les rapports corrects. Mais l'\xe9tudiant n'a d\xe9velopp\xe9 aucune des comp\xe9tences que le laboratoire devait enseigner."}),(0,t.jsxs)("p",{children:["L'\xe9valuation orient\xe9e processus pour les laboratoires signifie suivre ",(0,t.jsx)("em",{children:"comment"})," un \xe9tudiant aborde une exp\xe9rience. A-t-il formul\xe9 une hypoth\xe8se avant de commencer ? A-t-il test\xe9 les variables syst\xe9matiquement ou au hasard ? Quand les r\xe9sultats l'ont surpris, a-t-il enqu\xeat\xe9 ou ignor\xe9 ? A-t-il interpr\xe9t\xe9 les donn\xe9es de mani\xe8re r\xe9fl\xe9chie ou tir\xe9 des conclusions h\xe2tives ? Ces questions abordent ce que l'\xe9ducation en laboratoire vise r\xe9ellement \xe0 d\xe9velopper : la pens\xe9e scientifique."]}),(0,t.jsx)("h2",{children:"Comment WhimsyLabs a construit l'\xe9valuation des processus"}),(0,t.jsx)("p",{children:"Chez WhimsyLabs, l'\xe9valuation orient\xe9e processus n'est pas une adaptation en r\xe9ponse \xe0 l'IA. C'est ainsi que nous avons con\xe7u notre plateforme d\xe8s le d\xe9part. Nos laboratoires virtuels capturent chaque action qu'un \xe9tudiant effectue : quel \xe9quipement il s\xe9lectionne, dans quel ordre il ex\xe9cute les \xe9tapes, comment il r\xe9agit aux r\xe9sultats inattendus et comment sa technique s'am\xe9liore au fil du temps. Cette journalisation des interactions cr\xe9e un enregistrement d\xe9taill\xe9 de la pens\xe9e scientifique en action."}),(0,t.jsxs)("p",{children:[(0,t.jsx)("strong",{children:"La journalisation des actions"})," est le fondement. Lorsqu'un \xe9tudiant mesure la temp\xe9rature, nous enregistrons non seulement la lecture finale mais quand il l'a prise, combien de lectures il a faites et s'il a attendu que le thermom\xe8tre se stabilise. Quand il pipette une solution, nous suivons sa technique, y compris l'angle, la vitesse et s'il a pr\xe9-mouill\xe9 la pointe."]}),(0,t.jsxs)("p",{children:[(0,t.jsx)("strong",{children:"La notation de la technique"})," s'appuie sur la journalisation des actions pour \xe9valuer la comp\xe9tence proc\xe9durale. Notre tuteur IA, WhimsyCat, \xe9value non seulement les r\xe9sultats mais l'ex\xe9cution. Un \xe9tudiant qui atteint le point final correct dans un titrage avec une technique n\xe9glig\xe9e re\xe7oit un feedback diff\xe9rent de celui dont la technique \xe9tait pr\xe9cise mais qui a mal calcul\xe9 la molarit\xe9."]}),(0,t.jsxs)("p",{children:[(0,t.jsx)("strong",{children:"La comparaison avec les parcours experts"})," place le comportement de l'\xe9tudiant en contexte. Nous avons cartographi\xe9 comment les scientifiques experts abordent les exp\xe9riences courantes, identifiant les arbres de d\xe9cision et les sch\xe9mas de r\xe9solution de probl\xe8mes qui caract\xe9risent la pens\xe9e scientifique habile. Quand l'approche d'un \xe9tudiant diverge significativement des parcours experts, cela signale une opportunit\xe9 d'orientation cibl\xe9e."]}),(0,t.jsx)("h2",{children:"Ce que la recherche soutient"}),(0,t.jsxs)("p",{children:["La recommandation de l'OCDE s'aligne avec des d\xe9cennies de recherche en \xe9ducation. La revue historique de Black et Wiliam de 1998 a d\xe9montr\xe9 que l'\xe9valuation formative, le feedback fourni pendant l'apprentissage plut\xf4t qu'apr\xe8s, produit des gains d'apprentissage substantiels dans toutes les mati\xe8res et groupes d'\xe2ge. Leur m\xe9ta-analyse a trouv\xe9 des tailles d'effet entre 0,4 et 0,7, plus grandes que presque toute autre intervention \xe9ducative (",(0,t.jsx)("a",{href:"https://journals.sagepub.com/doi/10.3102/00346543068002249",target:"_blank",rel:"noopener noreferrer",children:"Black & Wiliam, 1998"}),")."]}),(0,t.jsx)("p",{children:"Des travaux plus r\xe9cents se sont concentr\xe9s sp\xe9cifiquement sur le raisonnement scientifique. La recherche sur les laboratoires virtuels a montr\xe9 que les syst\xe8mes qui capturent les donn\xe9es de processus peuvent identifier des misconceptions que les \xe9valuations traditionnelles manquent compl\xe8tement."}),(0,t.jsx)("h2",{children:"Implications pour les \xe9coles et les enseignants"}),(0,t.jsx)("p",{children:"La recommandation de l'OCDE a des implications significatives pour la fa\xe7on dont les \xe9coles abordent l'\xe9valuation. Le rapport note que l'IA peut r\xe9duire le temps pass\xe9 sur les t\xe2ches administratives d'environ 31%, mais seulement si les \xe9coles repensent ce que ces t\xe2ches impliquent. Si les enseignants continuent de noter les produits plut\xf4t que les processus, l'IA n'apporte pas d'aide significative et peut m\xeame augmenter la charge de travail par les efforts de d\xe9tection."}),(0,t.jsx)("p",{children:"L'\xe9valuation orient\xe9e processus n\xe9cessite une infrastructure diff\xe9rente. Les \xe9coles ont besoin d'environnements d'apprentissage qui capturent les donn\xe9es de processus, ce que fournit pr\xe9cis\xe9ment la technologie \xe9ducative con\xe7ue \xe0 cet effet. Les chatbots g\xe9n\xe9riques ne peuvent pas suivre le raisonnement des \xe9tudiants \xe0 travers une exp\xe9rience de chimie. Les laboratoires virtuels con\xe7us pour la capture de processus le peuvent."}),(0,t.jsx)("p",{children:"La transition n\xe9cessite \xe9galement un d\xe9veloppement professionnel. Les enseignants habitu\xe9s \xe0 corriger des rapports de laboratoire ont besoin de soutien pour interpr\xe9ter les journaux d'interaction, les m\xe9triques de technique et les analyses de parcours. Le rapport de l'OCDE appelle explicitement \xe0 \"de nouvelles voies de comp\xe9tences et cadres de formation\" pour aider les \xe9ducateurs \xe0 travailler efficacement avec les syst\xe8mes d'\xe9valuation am\xe9lior\xe9s par l'IA."}),(0,t.jsx)("h2",{children:"Le d\xe9fi de la mise en \u0153uvre"}),(0,t.jsx)("p",{children:"Passer de l'\xe9valuation des r\xe9sultats \xe0 celle des processus n'est pas simple. Cela n\xe9cessite de repenser ce que repr\xe9sentent les notes, de reconcevoir les grilles d'\xe9valuation et d'aider les \xe9tudiants \xe0 comprendre pourquoi le voyage compte autant que la destination. Les \xe9tudiants habitu\xe9s \xe0 \xeatre jug\xe9s uniquement sur les r\xe9ponses finales peuvent initialement r\xe9sister aux syst\xe8mes d'\xe9valuation qui \xe9valuent leur approche."}),(0,t.jsx)("p",{children:"Il y a aussi des pr\xe9occupations concernant l'\xe9quit\xe9. L'\xe9valuation orient\xe9e processus repose sur une technologie qui capture le comportement des \xe9tudiants, ce qui n\xe9cessite des appareils, une connectivit\xe9 et un support technique que toutes les \xe9coles n'ont pas actuellement. Le rapport de l'OCDE reconna\xeet cela, notant l'\xe9mergence d'une \"seconde fracture num\xe9rique\" bas\xe9e non pas sur l'acc\xe8s mais sur la qualit\xe9 de l'utilisation."}),(0,t.jsx)("p",{children:"WhimsyLabs a con\xe7u notre plateforme pour fonctionner sur des Chromebooks standards sur des r\xe9seaux scolaires typiques pr\xe9cis\xe9ment parce que les contraintes d'infrastructure sont r\xe9elles. Nous ne pouvons pas r\xe9soudre la fracture num\xe9rique, mais nous pouvons nous assurer que l'\xe9valuation orient\xe9e processus ne n\xe9cessite pas de mat\xe9riel sp\xe9cialis\xe9 que de nombreuses \xe9coles ne peuvent pas se permettre."}),(0,t.jsx)("h2",{children:"Quelle est la suite"}),(0,t.jsx)("p",{children:"L'approbation par l'OCDE de l'\xe9valuation orient\xe9e processus est significative car elle fournit une validation internationale pour une approche qui gagne en momentum dans la recherche en \xe9ducation depuis des ann\xe9es. Les \xe9coles et les d\xe9cideurs politiques qui attendaient des orientations faisant autorit\xe9 les ont maintenant. La question n'est plus de savoir s'il faut passer \xe0 l'\xe9valuation des processus, mais \xe0 quelle vitesse et avec quelle efficacit\xe9 ce changement peut se produire."}),(0,t.jsx)("p",{children:"Pour WhimsyLabs, ce moment est encourageant mais pas surprenant. Nous avons construit notre plateforme autour de l'\xe9valuation des processus parce que la recherche la soutenait, parce que l'\xe9ducation en laboratoire l'exige et parce que nous croyions que l'IA finirait par rendre l'\xe9valuation bas\xe9e uniquement sur les r\xe9sultats intenable. Le rapport de l'OCDE confirme ce vers quoi nous travaillons : un avenir o\xf9 les \xe9tudiants sont \xe9valu\xe9s sur leur r\xe9flexion, pas seulement sur leurs r\xe9ponses."}),(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)("h2",{children:"Articles connexes"}),(0,t.jsxs)("ul",{children:[(0,t.jsx)("li",{children:(0,t.jsx)("a",{href:"/fr/blog/process-based-lab-assessment-future",children:"\xc9valuer le processus, pas la r\xe9ponse : L'avenir de l'\xe9valuation en laboratoire"})}),(0,t.jsx)("li",{children:(0,t.jsx)("a",{href:"/fr/blog/ai-text-grading-fails-process-assessment-works",children:"Pourquoi la notation de texte par IA \xe9choue et l'\xe9valuation des processus fonctionne"})}),(0,t.jsx)("li",{children:(0,t.jsx)("a",{href:"/fr/blog/oecd-ai-learning-paradox-virtual-labs",children:"Le paradoxe de l'apprentissage par IA de l'OCDE et ce qu'il signifie pour les laboratoires virtuels"})})]})]}),(0,t.jsxs)("div",{className:"references-section",children:[(0,t.jsx)("h3",{children:"R\xe9f\xe9rences"}),(0,t.jsxs)("ul",{className:"references-list",children:[(0,t.jsxs)("li",{children:["Black, P., & Wiliam, D. (1998). Assessment and classroom learning. ",(0,t.jsx)("em",{children:"Assessment in Education: Principles, Policy & Practice, 5"}),"(1), 7-74."," ",(0,t.jsx)("a",{href:"https://journals.sagepub.com/doi/10.3102/00346543068002249",target:"_blank",rel:"noopener noreferrer",children:"https://doi.org/10.3102/00346543068002249"})]},"ref-1"),(0,t.jsxs)("li",{children:["European Platform for Adult Learning in Europe (EPALE). (2026). The Future of Learning: Key Takeaways from the OECD Digital Education Outlook 2026."," ",(0,t.jsx)("a",{href:"https://epale.ec.europa.eu/en/blog/future-learning-key-takeaways-oecd-digital-education-outlook-2026",target:"_blank",rel:"noopener noreferrer",children:"https://epale.ec.europa.eu/en/blog/future-learning-key-takeaways-oecd-digital-education-outlook-2026"})]},"ref-2"),(0,t.jsxs)("li",{children:["OCDE. (2026). OECD Digital Education Outlook 2026: Exploring Effective Uses of Generative AI in Education. OECD Publishing."," ",(0,t.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html"})]},"ref-3"),(0,t.jsxs)("li",{children:["O'Kelly, E. (2026). Warning over uncritical AI use in education. RTE News."," ",(0,t.jsx)("a",{href:"https://www.rte.ie/news/education/2026/0119/1553973-ai-education/",target:"_blank",rel:"noopener noreferrer",children:"https://www.rte.ie/news/education/2026/0119/1553973-ai-education/"})]},"ref-4")]})]})]})}}]);
